class Hesap:
    def __init__(self, sahip, bakiye=0):
        self.sahip = sahip
        self.bakiye = bakiye
        self.hareketler = []

    def yatir(self, tutar):
        if tutar <= 0:
            raise ValueError("tutar pozitif olmalı")
        self.bakiye += tutar
        self.hareketler.append(("yatir", tutar))
        return self.bakiye

    def cek(self, tutar):
        if tutar <= 0:
            raise ValueError("tutar pozitif olmalı")
        if tutar > self.bakiye:
            raise ValueError("yetersiz bakiye")
        self.bakiye -= tutar
        self.hareketler.append(("cek", tutar))
        return self.bakiye
